#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using A = std::allocator<int>;
    using T = std::allocator_traits<A>;
    A allocator;
    auto block = T::allocate_at_least(allocator, 3);
    static_assert(
        std::is_same_v<decltype(block), std::allocation_result<int *, std::size_t>>);
    assert(block.count >= 3);
    T::construct(allocator, block.ptr, 42);
    assert(*block.ptr == 42);
    T::destroy(allocator, block.ptr);
    T::deallocate(allocator, block.ptr, block.count);
    int *storage = T::allocate(allocator, 1);
    T::deallocate(allocator, storage, 1);
    auto copy = T::select_on_container_copy_construction(allocator);
    assert(copy == allocator);
}
